#include "metaFunctionalOptionObject.h"

// THE CONSTANT'S PLATE, WITH A SWITCH FOR ITS SIGN. An option IS a constant, so it keeps the plate the
// constant and the session parameter share and the stroke on the right that stands for the value; where
// the constant shows π, the option shows what its value is — on or off. Drawn from its SVG by
// tools/pictures/render.js (meta/functionalOption).

/* PNG */
static const wxString s_functionalOption_16_png = wxT("");

wxIcon ibValueMetaObjectFunctionalOption::GetIcon() const
{
	return GetIconGroup();
}

wxIcon ibValueMetaObjectFunctionalOption::GetIconGroup()
{
	static wxIcon icon =
		ibBackendPicture::GetIconFromBase64(s_functionalOption_16_png, wxSize(16, 16));

	return icon;
}
